  seed.update({'view':'result','completed':True,'accepted':[{'id':1},{'id':2},{'id':3}]});c=context(b,key,seed,w=1280,h=600);page=c.new_page();page.route('**/media/scene.mp4',lambda r:r.abort());page.goto('http://127.0.0.1:'+str(port));page.wait_for_function('!document.querySelector("#result-play").disabled');page.locator('#source-original').click();page.wait_for_function('document.querySelector("#result-play").getAttribute("aria-label")==="Повторить загрузку"');check(variant+' Result network failure has ordinary retry/source escape',page.locator('#result-media-status').is_visible() and page.locator('#source-dub').is_enabled() and page.locator('#result-play').is_enabled());page.unroute('**/media/scene.mp4');page.locator('#result-play').click();page.wait_for_function('!document.querySelector("#result-play").disabled&&document.querySelector("#result-original").readyState>=2');check(variant+' media retry recovers paused finite source',page.locator('#result-original').evaluate('v=>v.paused&&v.duration>13'));c.close()
